INSERT INTO order_refund_record(
    refund_no, order_no, refund_amount, refund_reason, status, operator, payment_request_no, create_time, update_time
) VALUES(
    #{refundNo}, #{orderNo}, #{amount}, #{reason}, #{status}, #{operator}, #{paymentRequestNo}, now(), now()
)
ON DUPLICATE KEY UPDATE update_time = now()

INSERT INTO order_adjust_record(
    adjust_no, order_no, adjust_type, adjust_amount, adjust_reason, status, operator, payment_request_no, create_time, update_time
) VALUES(
    #{adjustNo}, #{orderNo}, 'SUPPLEMENT_CHARGE', #{amount}, #{reason}, #{status}, #{operator}, #{paymentRequestNo}, now(), now()
)
ON DUPLICATE KEY UPDATE update_time = now()
